// Traduz o evento do WAHA para o vocabulário do inventário.
//
// Descarta o que NÃO pode virar atendimento — e cada descarte tem motivo:
//   fromMe  → é a nossa própria resposta voltando como eco;
//   @g.us   → grupo: cobrar dívida na frente de terceiros expõe o devedor;
//   sem texto → o modelo só guarda texto (áudio precisa de transcrição).
const eventos = [];

for (const item of $input.all()) {
  const corpo = item.json.body ?? item.json;
  if (corpo.event !== 'message') continue;

  const p = corpo.payload ?? {};
  if (p.fromMe === true) continue;

  const jid = String(p.from ?? '');
  const [numero, dominio] = jid.split('@');
  if (dominio !== 'c.us' && dominio !== 's.whatsapp.net') continue;

  const texto = typeof p.body === 'string' ? p.body.trim() : '';
  if (!texto) continue;

  eventos.push({
    json: {
      telefone: numero.replace(/\D/g, ''),
      nome: p.notifyName ?? p._data?.pushName ?? null,
      corpo: texto.slice(0, 5000),
      waId: typeof p.id === 'string' ? p.id : null,
    },
  });
}

return eventos;
